import Foundation

/// Contents of `announced-lineup.json`: next year's bill as the festival first announces
/// it, by day, before there are set times or stages.
///
/// Bundled only, and generated by `scripts/announced_lineup.py` from the announcement.
/// It is never merged into the schedule: the schedule needs a start and end for every set,
/// and next year's `schedule.json` on `main` would replace this year's on every phone.
/// `ScheduleStore.upcomingLineup` shows it only while its year is later than the
/// schedule's, so it steps aside once next year's set times arrive.
struct AnnouncedLineup: Codable, Equatable {
    let version: Int
    let generatedAt: Date
    let year: Int
    /// `yyyy-MM-dd`, the first and last days of the announced weekend.
    let startDate: String
    let endDate: String
    let days: [AnnouncedDay]

    var artistCount: Int { days.reduce(0) { $0 + $1.artists.count } }

    /// The first name on each day, which is how the festival bills its headliners.
    var headliners: [String] { days.compactMap { $0.artists.first?.name } }
}

struct AnnouncedDay: Codable, Equatable, Identifiable {
    /// `yyyy-MM-dd`.
    let date: String
    let weekday: String
    /// Billing order, headliner first.
    let artists: [AnnouncedArtist]

    var id: String { date }
}

struct AnnouncedArtist: Codable, Equatable, Identifiable, Hashable {
    let id: String
    let name: String
    /// Billed as "a special performance by", at the foot of the day.
    var special: Bool? = nil

    var isSpecial: Bool { special == true }
}
